import{_ as h,o as i,c as a,a2 as t}from"./chunks/framework.mRCPFc5l.js";const m=JSON.parse('{"title":"Vì sao hai learner cùng tuổi nhận gợi ý khác nhau","description":"","frontmatter":{},"headers":[],"relativePath":"decisions/khac-goi-y.md","filePath":"decisions/khac-goi-y.md"}'),c={name:"decisions/khac-goi-y.md"};function g(o,n,u,r,s,e){return i(),a("div",null,[...n[0]||(n[0]=[t('<h1 id="vi-sao-hai-learner-cung-tuoi-nhan-goi-y-khac-nhau" tabindex="-1">Vì sao hai learner cùng tuổi nhận gợi ý khác nhau <a class="header-anchor" href="#vi-sao-hai-learner-cung-tuoi-nhan-goi-y-khac-nhau" aria-label="Permalink to &quot;Vì sao hai learner cùng tuổi nhận gợi ý khác nhau&quot;">​</a></h1><p>Trên trang này# Vì sao hai learner cùng tuổi nhận gợi ý khác nhau <a href="#vi-sao-hai-learner-cung-tuoi-nhan-goi-y-khac-nhau">​</a> Tuổi và lớp gần như không xuất hiện trong phép tính của Nemo12. Chúng chỉ dùng để chọn ngôn ngữ trình bày và bối cảnh ví dụ — không dùng để quyết định học gì.</p><h2 id="hai-ban-cung-lop-8-cung-điem-toan-7-5-​" tabindex="-1">Hai bạn, cùng lớp 8, cùng điểm Toán 7.5 <a href="#hai-ban-cung-lop-8-cung-điem-toan-7-5">​</a> <a class="header-anchor" href="#hai-ban-cung-lop-8-cung-điem-toan-7-5-​" aria-label="Permalink to &quot;Hai bạn, cùng lớp 8, cùng điểm Toán 7.5 [​](#hai-ban-cung-lop-8-cung-điem-toan-7-5)&quot;">​</a></h2><p>AnBìnhNền phân số, tỷ lệvững (0.88)hổng (0.51)Cách saisai ở bài dài, nhiều bướcsai ngay ở biến đổi cơ bảnMục tiêuthi chuyên, còn 9 thánghọc chắc chương trình, chưa thi gìThời gian mỗi tuần8 giờ3 giờHoàn cảnhổn địnhvừa ốm một tuầnLần cuối làm Hìnhhôm qua5 tuần trướcCùng một con số 7.5, nhưng gần như mọi thứ bên dưới đều khác. <strong>Gợi ý cho An:</strong> bài Hình khó hơn mức hiện tại, dạng đề thi chuyên. Nền đã vững, thời gian nhiều, mục tiêu đòi hỏi mức sâu cao — đây là lúc đẩy. <strong>Gợi ý cho Bình:</strong> quay lại phân số và tỷ lệ, mỗi buổi ngắn 20 phút. Nền đứt thì học chương mới không có tác dụng, và tuần này vừa ốm nên khối lượng phải nhẹ. Nếu chỉ nhìn &quot;lớp 8, Toán 7.5&quot;, hai bạn này nhận cùng một phiếu bài tập. Đó chính là điều đang xảy ra trong hầu hết các lớp học thêm.</p><h2 id="sau-thu-tao-ra-khac-biet-​" tabindex="-1">Sáu thứ tạo ra khác biệt <a href="#sau-thu-tao-ra-khac-biet">​</a> <a class="header-anchor" href="#sau-thu-tao-ra-khac-biet-​" aria-label="Permalink to &quot;Sáu thứ tạo ra khác biệt [​](#sau-thu-tao-ra-khac-biet)&quot;">​</a></h2><p><strong>Nền kiến thức.</strong> Cùng một điểm số có thể đến từ hai cấu trúc hiểu biết hoàn toàn khác nhau. Đây là yếu tố quan trọng nhất, và cũng là yếu tố mà điểm số che giấu kỹ nhất. <strong>Kiểu sai.</strong> Sai vì cẩu thả, sai vì đọc nhầm đề, sai vì thiếu nền, sai vì chưa gặp dạng này — bốn nguyên nhân dẫn tới bốn hành động khác nhau. Cùng cho ra một dấu gạch đỏ. <strong>Mục tiêu.</strong> Không có mục tiêu thì không có &quot;quan trọng&quot;. Cùng một mảng kiến thức có thể là sống còn với người này và ngoại vi với người kia. <strong>Thời gian còn lại.</strong> Còn 9 tháng thì xây nền. Còn 3 tuần thì củng cố thứ đã có. <strong>Hoàn cảnh.</strong> Ốm, thi học kỳ, tuần bận, vừa mất tự tin ở một môn — tất cả đổi việc nên làm hôm nay mà không đổi gì về năng lực. <strong>Trạng thái trí nhớ.</strong> Từng học rồi nhưng 5 tuần chưa dùng thì khác hẳn vừa học hôm qua — dù mức vững ghi nhận là như nhau.</p><h2 id="vi-sao-tuoi-lai-la-chi-dau-kem-​" tabindex="-1">Vì sao tuổi lại là chỉ dấu kém <a href="#vi-sao-tuoi-lai-la-chi-dau-kem">​</a> <a class="header-anchor" href="#vi-sao-tuoi-lai-la-chi-dau-kem-​" aria-label="Permalink to &quot;Vì sao tuổi lại là chỉ dấu kém [​](#vi-sao-tuoi-lai-la-chi-dau-kem)&quot;">​</a></h2><p>Xếp trẻ theo năm sinh là một giải pháp <strong>hậu cần</strong>, không phải một kết luận về việc học. Nó tồn tại vì trường học cần chia lớp, không phải vì trẻ cùng tuổi thì học giống nhau. Trong thực tế, độ chênh về kiến thức nền trong một lớp thường lớn hơn nhiều so với độ chênh giữa hai lớp liền kề. Một lớp 8 điển hình chứa những học sinh đang ở trình độ lớp 6 và những học sinh đang ở trình độ lớp 10 — ở cùng một môn. Nemo12 đưa learner vào <strong>đúng chỗ con đang ở</strong>. Việc đó không kèm nhãn dán nào, không thông báo cho ai, và không có gì đáng xấu hổ. Học phân số ở lớp 8 chỉ là việc cần làm.</p><h2 id="đieu-nay-nghia-la-gi-voi-viec-so-sanh-​" tabindex="-1">Điều này nghĩa là gì với việc so sánh <a href="#đieu-nay-nghia-la-gi-voi-viec-so-sanh">​</a> <a class="header-anchor" href="#đieu-nay-nghia-la-gi-voi-viec-so-sanh-​" aria-label="Permalink to &quot;Điều này nghĩa là gì với việc so sánh [​](#đieu-nay-nghia-la-gi-voi-viec-so-sanh)&quot;">​</a></h2><p>So sánh gợi ý của con bạn với gợi ý của con nhà khác gần như không cho thông tin gì. Hai hệ thống gợi ý khác nhau vì sáu yếu tố ở trên khác nhau — không phải vì một đứa giỏi hơn đứa kia. Con bạn được ôn lại nhiều hơn có thể vì con nghỉ hè hai tháng không đụng tới môn đó. Con nhà kia được học phần mới có thể vì bạn ấy vừa làm một bài đo tuần trước nên hệ thống đang tự tin về nền của bạn ấy. Câu hỏi đáng hỏi Không phải <em>&quot;vì sao con nhà kia học phần cao hơn?&quot;</em> mà là: <strong>&quot;Gợi ý này dựa trên bằng chứng nào về con tôi?&quot;</strong> — câu này luôn có câu trả lời cụ thể. Cá nhân hoá không phải cho mỗi đứa trẻ một giao diện khác nhau. Nó là thừa nhận rằng cùng một điểm số có thể có sáu nguyên nhân khác nhau, và mỗi nguyên nhân cần một hành động khác nhau. <a href="/decisions/readiness-vs-mastery">Readiness khác Mastery thế nào →</a></p>',10)])])}const k=h(c,[["render",g]]);export{m as __pageData,k as default};
